new file mode 100644
index 000000000..c109c7dac
--- /dev/null
+++ b/daemon/actions/bundled/turnoffkeyboardbacklight.cpp
@@ -0,0 +1,78 @@
+/*
+ *   SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ *   SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "turnoffkeyboardbacklight.h"
+
+#include <PowerDevilProfileSettings.h>
+#include <powerdevil_debug.h>
+#include <powerdevilcore.h>
+
+#include <QDebug>
+
+#include <KPluginFactory>
+
+K_PLUGIN_CLASS_WITH_JSON(PowerDevil::BundledActions::TurnOffKeyboardBacklight, "powerdevilturnoffkeyboardbacklightaction.json")
+
+namespace PowerDevil::BundledActions
+{
+TurnOffKeyboardBacklight::TurnOffKeyboardBacklight(QObject *parent)
+    : Action(parent)
+{
+}
+
+void TurnOffKeyboardBacklight::onWakeupFromIdle()
+{
+    restoreBrightness();
+}
+
+void TurnOffKeyboardBacklight::onIdleTimeout(std::chrono::milliseconds /*timeout*/)
+{
+    // Leave the backlight alone if it's already off, e.g. turned off by the user or by the DimDisplay or DPMS actions,
+    // so that we don't turn it back on when waking up.
+    const int brightness = core()->keyboardBrightnessController()->brightness();
+    if (brightness <= 0) {
+        return;
+    }
+
+    qCDebug(POWERDEVIL) << "TurnOffKeyboardBacklight: turning off keyboard backlight on idle timeout";
+    m_oldKeyboardBrightness = brightness;
+    core()->keyboardBrightnessController()->setBrightness(0);
+}
+
+void TurnOffKeyboardBacklight::restoreBrightness()
+{
+    if (m_oldKeyboardBrightness <= 0) {
+        return;
+    }
+
+    qCDebug(POWERDEVIL) << "TurnOffKeyboardBacklight: restoring keyboard backlight";
+    core()->keyboardBrightnessController()->setBrightness(m_oldKeyboardBrightness);
+    m_oldKeyboardBrightness = 0;
+}
+
+bool TurnOffKeyboardBacklight::isSupported()
+{
+    return core()->keyboardBrightnessController()->isSupported();
+}
+
+bool TurnOffKeyboardBacklight::loadAction(const PowerDevil::ProfileSettings &profileSettings)
+{
+    if (!profileSettings.turnOffKeyboardBacklightWhenIdle() || profileSettings.turnOffKeyboardBacklightIdleTimeoutSec() <= 0) {
+        restoreBrightness();
+        return false;
+    }
+
+    const std::chrono::seconds idleTimeout(profileSettings.turnOffKeyboardBacklightIdleTimeoutSec());
+    qCDebug(POWERDEVIL) << "TurnOffKeyboardBacklight: registering idle timeout after" << idleTimeout;
+    registerIdleTimeout(idleTimeout);
+    return true;
+}
+
+}
+
+#include "turnoffkeyboardbacklight.moc"
+
+#include "moc_turnoffkeyboardbacklight.cpp"
