+ */
+
+#pragma once
+
+#include <powerdevilaction.h>
+
+namespace PowerDevil::BundledActions
+{
+class TurnOffKeyboardBacklight : public PowerDevil::Action
+{
+    Q_OBJECT
+
+public:
+    explicit TurnOffKeyboardBacklight(QObject *parent);
+
+protected:
+    void onWakeupFromIdle() override;
+    void onIdleTimeout(std::chrono::milliseconds timeout) override;
+    bool isSupported() override;
+
+public:
+    bool loadAction(const PowerDevil::ProfileSettings &profileSettings) override;
+
+private:
+    void restoreBrightness();
+
+    int m_oldKeyboardBrightness = 0;
+};
+
+}
diff --git a/kcm/ui/ProfileConfig.qml b/kcm/ui/ProfileConfig.qml
index c88120439..ca2795d18 100644
--- a/kcm/ui/ProfileConfig.qml
+++ b/kcm/ui/ProfileConfig.qml
@@ -631,6 +631,67 @@ Kirigami.FormLayout {
         }
     }

+    TimeDurationComboBox {
+        id: turnOffKeyboardBacklightIdleTimeoutCombo
+        visible: kcm.supportedActions["TurnOffKeyboardBacklight"] === true
+        Layout.fillWidth: true
+        Kirigami.FormData.label: i18nc("@label:combobox Turn off keyboard backlight after X seconds", "Turn off keyboard bac&klight:")
+
+        durationPromptLabel: i18nc("@label:spinbox Turn off keyboard backlight after X seconds", "Turn off keyboard backlight after:")
+        durationPromptAcceptsUnits: [DurationPromptDialog.Unit.Seconds, DurationPromptDialog.Unit.Minutes]
+
+        function translateSeconds(n, formatUnit = DurationPromptDialog.Unit.Seconds) {
+            return formatUnit == DurationPromptDialog.Unit.Minutes
+                ? translateMinutes(n / 60) : i18ncp("@option:combobox", "%1 second", "%1 seconds", n);
+        }
+        function translateMinutes(n) { return i18ncp("@option:combobox", "%1 minute", "%1 minutes", n); }
+
+        valueRole: "seconds"
+        textRole: "text"
+        unitOfValueRole: DurationPromptDialog.Unit.Seconds
+        durationPromptFromValue: 5
+        presetOptions: [
+            { seconds: -1, text: i18nc("@option:combobox Turn off keyboard backlight automatically", "Never") },
+            { seconds: 10, text: translateSeconds(10), unit: DurationPromptDialog.Unit.Seconds },
+            { seconds: 30, text: translateSeconds(30), unit: DurationPromptDialog.Unit.Seconds },
+            { seconds: 1 * 60, text: translateMinutes(1), unit: DurationPromptDialog.Unit.Minutes },
+            { seconds: 2 * 60, text: translateMinutes(2), unit: DurationPromptDialog.Unit.Minutes },
+            { seconds: 5 * 60, text: translateMinutes(5), unit: DurationPromptDialog.Unit.Minutes },
+            { seconds: -2, text: i18nc("@option:combobox Choose a custom value outside the list of preset values", "Custom…") },
+        ]
+        customRequesterValue: -2
+        configuredValue: root.profileSettings.turnOffKeyboardBacklightWhenIdle ? root.profileSettings.turnOffKeyboardBacklightIdleTimeoutSec : -1
+        configuredDisplayUnit: model[indexOfValue(configuredValue)]?.unit ?? DurationPromptDialog.Unit.Seconds
+
+        onRegularValueActivated: {
+            root.profileSettings.turnOffKeyboardBacklightIdleTimeoutSec = currentValue;
+            root.profileSettings.turnOffKeyboardBacklightWhenIdle = currentValue > 0;
+        }
+        onCustomDurationAccepted: {
+            root.profileSettings.turnOffKeyboardBacklightIdleTimeoutSec = valueToUnit(
+                customDuration.value, customDuration.unit, DurationPromptDialog.Unit.Seconds);
+            root.profileSettings.turnOffKeyboardBacklightWhenIdle = customDuration.value > 0;
+        }
+
+        onConfiguredValueOptionMissing: {
+            const unit = configuredValue % 60 === 0
+                ? customDuration?.unit ?? DurationPromptDialog.Unit.Minutes
+                : DurationPromptDialog.Unit.Seconds;
+
+            customOptions = [{
+                seconds: configuredValue,
+                text: translateSeconds(configuredValue, unit),
+                unit: unit,
+            }];
+            customDuration = null;
+        }
+
+        KCM.SettingStateBinding {
+            configObject: root.profileSettings
+            settingName: "TurnOffKeyboardBacklightIdleTimeoutSec"
+        }
+    }
+
     //
     // Advanced customization options

